#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int h, w;
    scanf("%d %d", &h, &w);
    getchar();

    int mass_count = 0;
    int column_sum = 0;
    int support = 0;
    char line[502];

    for (int row = 0; row < h; row++) {
        fgets(line, sizeof(line), stdin);

        for (int column = 0; column < w; column++) {
            if (line[column] == '#') {
                mass_count++;
                column_sum += column;
            } else if (line[column] == 'X') {
                support = column;
            }
        }
    }

    // Intuitive equation:
    // -0.5 <= mean - support <= 0.5
    // |mean - support| <= 0.5
    // mean = column_sum / mass_count
    //
    // Multiply both sides by 2 * mass_count to avoid division:
    // 2 * mass_count * |column_sum / mass_count - support|
    //     <= 0.5 * 2 * mass_count
    // 2 * |column_sum - mass_count * support| <= mass_count
    //
    // Name the expression inside the absolute value relative_sum.
    int relative_sum = column_sum - mass_count * support;
    int balanced = 2 * abs(relative_sum) <= mass_count;

    double center_of_mass = (double) relative_sum / mass_count;

    printf("%.6f\n", center_of_mass);
    puts(balanced ? "In balance" : "Not in balance");

    return 0;
}
